<script lang="ts">
  import { onMount } from 'svelte';
  import { EventsOn } from '../wailsjs/runtime/runtime';
  import logo from './assets/release-launcher-logo.png';
  import { CancelBuild, DeleteProject, GetDaliConfig, GetPackagePlan, GetProjects, GetRecentRuns, GetTransferPlan, OpenReleaseFolder, PickDirectory, PickFile, SaveDaliConfig, SaveProject, StartBuild, StartBuildAndPackage, StartBuildPackageAndSend, StartPackage, StartTransfer } from './backend';
  import type { BuildEvent, BuildOutputLine, BuildRun, Component, DaliConfig, EnvironmentProfile, PackagePlan, PackageRequest, PackageRun, Project, ReleaseRun, RunSummary, TransferRequest, TransferRun, ValidationIssue } from './types';

  type View = 'release' | 'projects' | 'activity' | 'settings';
  type Operation = 'build' | 'package' | 'transfer' | 'release' | 'release-transfer';
  let view: View = 'release'; let step = 1; let loading = true; let saving = false; let daliSaving = false;
  let projects: Project[] = []; let selectedProjectId = ''; let selectedComponentIds: string[] = []; let selectedProject: Project | null = null;
  let releaseEnvironment = ''; let packageVersion = '1.0.0'; let operation: Operation = 'release'; let packageTemplate = ''; let overwrite = false; let componentFilter = '';
  let namingPlan: PackagePlan | null = null; let namingNames: Record<string, string> = {}; let buildReview = false;
  let buildRun: BuildRun | null = null; let packageRun: PackageRun | null = null; let transferRun: TransferRun | null = null; let releaseRun: ReleaseRun | null = null;
  let buildOutput: BuildOutputLine[] = []; let pendingBuildEvents: BuildEvent[] = []; let operationStarting = false; let activity: RunSummary[] = [];
  let activityStatus = 'all'; let activityProject = ''; let activityEnvironment = 'all'; let settingsProject: Project | null = null; let settingsIsNew = false;
  let settingsTab: 'general' | 'components' | 'environments' = 'general'; let selectedEnvironmentId = ''; let issues: ValidationIssue[] = []; let errorMessage = ''; let successMessage = ''; let namingError = ''; let deleteCandidate: Project | null = null;
  let daliConfig: DaliConfig = { executable: 'dali', peerName: '', peerAddress: '', auto: true, wait: false }; let newComponentSequence = 0;
  let environmentDeleteCandidate: EnvironmentProfile | null = null;
  let notificationTimer: ReturnType<typeof setTimeout> | null = null;

  $: selectedProject = projects.find((project) => project.id === selectedProjectId) ?? null;
  $: environments = selectedProject?.environments?.length ? selectedProject.environments : legacyEnvironments(selectedProject);
  $: activeEnvironment = environments.find((environment) => environment.id === releaseEnvironment) ?? environments[0];
  $: selectedEnvironmentProfile = settingsProject?.environments?.find((environment) => environment.id === selectedEnvironmentId) ?? settingsProject?.environments?.[0] ?? null;
  $: if (successMessage || errorMessage) scheduleNotificationDismissal();
  $: operationActive = operationStarting || currentRun?.status === 'running' || namingPlan !== null || buildReview;
  $: currentRun = buildRun ?? packageRun ?? transferRun ?? releaseRun;
  $: filteredActivity = activity.filter((run) => (activityStatus === 'all' || run.status === activityStatus) && (!activityProject || run.projectId === activityProject) && (activityEnvironment === 'all' || run.environment === activityEnvironment));

  onMount(() => { const stopListening = EventsOn('release-launcher:build-event', (event: BuildEvent) => handleBuildEvent(event)); void loadProjects(); return stopListening; });
  async function loadProjects() { loading = true; try { const [loadedProjects, loadedDali] = await Promise.all([GetProjects(), GetDaliConfig()]); projects = loadedProjects; daliConfig = loadedDali; selectedProjectId = projects[0]?.id ?? ''; selectedComponentIds = projects[0]?.components.map((component) => component.id) ?? []; releaseEnvironment = projects[0]?.defaultEnvironment ?? projects[0]?.environments?.[0]?.id ?? 'dev'; await loadActivity(); } catch (error) { errorMessage = readableError(error); } finally { loading = false; } }
  async function loadActivity() { try { activity = await GetRecentRuns('', 100); } catch (error) { errorMessage = readableError(error); } }
  function selectProject(id: string) { if (operationActive) return; selectedProjectId = id; const project = projects.find((item) => item.id === id); selectedComponentIds = project?.components.map((component) => component.id) ?? []; releaseEnvironment = project?.defaultEnvironment ?? project?.environments?.[0]?.id ?? 'dev'; }
  function selectEnvironment(id: string) { if (!operationActive) releaseEnvironment = id; }
  function setOperation(event: Event) { operation = selectValue(event) as Operation; }
  function toggleComponent(component: Component) { if (!operationActive) selectedComponentIds = selectedComponentIds.includes(component.id) ? selectedComponentIds.filter((id) => id !== component.id) : [...selectedComponentIds, component.id]; }
  function selectAllComponents() { if (selectedProject) selectedComponentIds = selectedProject.components.map((component) => component.id); }
  function selectNoComponents() { selectedComponentIds = []; }
  function resetRunState() { buildRun = null; packageRun = null; transferRun = null; releaseRun = null; buildOutput = []; pendingBuildEvents = []; errorMessage = ''; successMessage = ''; namingError = ''; overwrite = false; namingPlan = null; buildReview = false; }
  function continueToReview() { if (!selectedProject) { errorMessage = 'Create or select a project first.'; return; } if (selectedComponentIds.length === 0) { errorMessage = 'Select at least one component.'; return; } resetRunState(); if (operation === 'build') { buildReview = true; step = 2; return; } void prepareNaming(); }
  async function prepareNaming() { if (!selectedProject) return; operationStarting = true; try { const plan = await GetPackagePlan({ ...packageRequest(), packageNames: {} }); if (operation === 'transfer') { const transferPlan = await GetTransferPlan({ ...packageRequest(), packageNames: Object.fromEntries(plan.components.filter((item) => item.selected && item.enabled).map((item) => [item.componentId, item.resolvedFilename ?? ''])) } as TransferRequest); if (transferPlan.hasMissing) throw new Error('One or more selected packages do not exist. Package them before sending.'); } namingPlan = plan; const approved = namingNames; namingNames = Object.fromEntries(plan.components.filter((item) => item.selected && item.enabled).map((item) => [item.componentId, approved[item.componentId] ?? item.resolvedFilename ?? ''])); step = 2; } catch (error) { errorMessage = readableError(error); } finally { operationStarting = false; } }
  function packageRequest(): PackageRequest { return { projectId: selectedProject?.id ?? '', componentIds: selectedComponentIds, version: packageVersion.trim(), overwrite, filenameTemplate: packageTemplate.trim(), packageNames: { ...namingNames }, environment: releaseEnvironment }; }
  async function editPackageName(componentId: string, value: string) { namingNames = { ...namingNames, [componentId]: value }; if (!namingPlan) return; try { namingPlan = await GetPackagePlan({ ...packageRequest(), packageNames: { ...namingNames } }); } catch (error) { namingError = readableError(error); } }
  async function confirmReview() { if (!selectedProject) return; if (operation === 'build') { await startBuild(); return; } if (!namingPlan) return; try { namingError = ''; const request = packageRequest(); namingPlan = await GetPackagePlan(request); if (operation === 'transfer') { const transferPlan = await GetTransferPlan(request as TransferRequest); if (transferPlan.hasMissing) throw new Error('One or more selected packages do not exist. Package them before sending.'); } if (namingPlan.hasConflicts && !overwrite) { namingError = 'Existing files need an explicit overwrite decision before this release can run.'; return; } await startApproved(request); } catch (error) { namingError = readableError(error); } }
  async function startBuild() { if (!selectedProject) return; operationStarting = true; step = 3; try { buildRun = await StartBuild({ projectId: selectedProject.id, componentIds: selectedComponentIds, environment: releaseEnvironment }); finishStarting(pendingBuildEvents); } catch (error) { operationStarting = false; step = 2; errorMessage = readableError(error); } }
  async function startApproved(request: PackageRequest) { operationStarting = true; step = 3; namingPlan = null; buildReview = false; try { if (operation === 'package') packageRun = await StartPackage(request); else if (operation === 'release') releaseRun = await StartBuildAndPackage(request); else if (operation === 'release-transfer') releaseRun = await StartBuildPackageAndSend(request); else if (operation === 'transfer') transferRun = await StartTransfer(request as TransferRequest); finishStarting(pendingBuildEvents); } catch (error) { operationStarting = false; step = 2; errorMessage = readableError(error); } }
  function finishStarting(events: BuildEvent[]) { operationStarting = false; pendingBuildEvents = []; events.forEach(applyBuildEvent); }
  function cancelFlow() { if (step === 2) { namingPlan = null; buildReview = false; step = 1; return; } void cancelOperation(); }
  async function cancelOperation() { const id = buildRun?.id ?? packageRun?.id ?? transferRun?.id ?? releaseRun?.id; if (!id) return; try { await CancelBuild(id); } catch (error) { errorMessage = readableError(error); } }
  function handleBuildEvent(event: BuildEvent) { if (operationStarting && !buildRun && !packageRun && !releaseRun && !transferRun) { pendingBuildEvents = [...pendingBuildEvents, event]; return; } applyBuildEvent(event); }
  function applyBuildEvent(event: BuildEvent) { if (event.phase === 'package') applyPackageEvent(event); else if (event.phase === 'transfer') applyTransferEvent(event); else if (event.phase === 'release') applyReleaseEvent(event); else applyBuildOnlyEvent(event); }
  function appendOutput(event: BuildEvent) { if (event.type === 'output' && event.text !== undefined) buildOutput = [...buildOutput, { componentName: event.componentName ?? 'Run', stream: event.stream ?? 'system', text: event.text }]; }
  function applyBuildOnlyEvent(event: BuildEvent) { if (!buildRun || buildRun.id !== event.runId) return; appendOutput(event); if (event.componentId && event.status) buildRun = { ...buildRun, components: buildRun.components.map((item) => item.componentId === event.componentId ? { ...item, status: event.status!, message: event.error || statusLabel(event.status!), result: event.result ?? item.result } : item) }; if (event.type === 'run_finished' && event.runStatus) { buildRun = { ...buildRun, status: event.runStatus, endTime: event.timestamp, error: event.error }; finishMessage(event.runStatus, event.error); } }
  function applyPackageEvent(event: BuildEvent) { if (!packageRun || packageRun.id !== event.runId) return; appendOutput(event); if (event.componentId && event.packageStatus) packageRun = { ...packageRun, components: packageRun.components.map((item) => item.componentId === event.componentId ? { ...item, status: event.packageStatus!, message: event.error || statusLabel(event.packageStatus!), result: event.packageResult ?? item.result } : item) }; if (event.type === 'package_run_finished' && event.runStatus) { packageRun = { ...packageRun, status: event.runStatus as PackageRun['status'], endTime: event.timestamp, error: event.error }; finishMessage(event.runStatus, event.error); } }
  function applyTransferEvent(event: BuildEvent) { if (!transferRun || transferRun.id !== event.runId) return; appendOutput(event); if (event.componentId && event.transferStatus) transferRun = { ...transferRun, components: transferRun.components.map((item) => item.componentId === event.componentId ? { ...item, status: event.transferStatus!, message: event.error || statusLabel(event.transferStatus!), result: event.transferResult ?? item.result } : item) }; if (event.type === 'transfer_run_finished' && event.runStatus) { transferRun = { ...transferRun, status: event.runStatus as TransferRun['status'], endTime: event.timestamp, error: event.error }; finishMessage(event.runStatus, event.error); } }
  function applyReleaseEvent(event: BuildEvent) { if (!releaseRun || releaseRun.id !== event.runId) return; appendOutput(event); if (event.componentId && event.status) releaseRun = { ...releaseRun, components: releaseRun.components.map((item) => item.componentId === event.componentId ? { ...item, buildStatus: event.status!, buildMessage: (event.error ?? '').split(' | ')[0] || item.buildMessage, buildResult: event.result ?? item.buildResult, packageStatus: event.packageStatus ?? item.packageStatus, packageMessage: (event.error ?? '').split(' | ')[1] || item.packageMessage, packageResult: event.packageResult ?? item.packageResult, transferStatus: event.transferStatus ?? item.transferStatus, transferMessage: (event.error ?? '').split(' | ')[2] || item.transferMessage, transferResult: event.transferResult ?? item.transferResult } : item) }; if (event.type === 'release_run_finished' && event.runStatus) { releaseRun = { ...releaseRun, status: event.runStatus as ReleaseRun['status'], endTime: event.timestamp, error: event.error }; finishMessage(event.runStatus, event.error); } }
  function finishMessage(status: string, error?: string) { if (status === 'completed') { successMessage = 'Run completed successfully.'; void loadActivity(); } else if (status === 'failed') errorMessage = error || 'Run failed.'; else if (status === 'cancelled') errorMessage = error || 'Run cancelled.'; }

  function openNewProject() { if (operationActive) return; settingsProject = { id: '', name: '', defaultEnvironment: 'dev', environments: defaultEnvironments(), components: [] }; settingsIsNew = true; selectedEnvironmentId = 'dev'; settingsTab = 'general'; issues = []; view = 'projects'; }
  function openProjectSettings(project: Project) { if (operationActive) return; settingsProject = structuredClone(project); settingsIsNew = false; selectedEnvironmentId = settingsProject.environments?.[0]?.id ?? ''; settingsTab = 'general'; issues = []; view = 'projects'; }
  function updateProject(changes: Partial<Project>) { if (settingsProject && !operationActive) settingsProject = { ...settingsProject, ...changes }; }
  function updateComponent(index: number, changes: Partial<Component>) { if (settingsProject && !operationActive) updateProject({ components: settingsProject.components.map((component, i) => i === index ? { ...component, ...changes } : component) }); }
  function addComponent() { if (settingsProject) updateProject({ components: [...settingsProject.components, emptyComponent()] }); }
  function removeComponent(index: number) { if (settingsProject) updateProject({ components: settingsProject.components.filter((_, i) => i !== index) }); }
  function openEnvironmentProfiles() { settingsTab = 'environments'; if (!selectedEnvironmentId) selectedEnvironmentId = settingsProject?.environments?.[0]?.id ?? ''; }
  function addEnvironment() { if (!settingsProject) return; const id = uniqueEnvironmentId(settingsProject.environments ?? []); updateProject({ environments: [...(settingsProject.environments ?? []), { id, name: id, commands: {} }] }); selectedEnvironmentId = id; }
  function duplicateEnvironment() { const source = selectedProfile(); if (!source || !settingsProject) return; const id = uniqueEnvironmentId(settingsProject.environments ?? []); updateProject({ environments: [...(settingsProject.environments ?? []), { id, name: `${source.name} Copy`, commands: { ...source.commands } }] }); selectedEnvironmentId = id; }
  function selectedProfile(profileID = selectedEnvironmentId): EnvironmentProfile | null { return settingsProject?.environments?.find((environment) => environment.id === profileID) ?? settingsProject?.environments?.[0] ?? null; }
  function profileCommands(profile: EnvironmentProfile | null): Record<string, string> { return profile?.commands ?? {}; }
  function updateProfile(changes: Partial<EnvironmentProfile>, profileID = selectedEnvironmentId) { if (!settingsProject) return; const profile = selectedProfile(profileID); if (!profile) return; const nextID = changes.id?.trim() || profile.id; const environments = (settingsProject.environments ?? []).map((item) => item.id === profile.id ? { ...item, ...changes, id: nextID, commands: item.commands ?? {} } : item); updateProject({ environments, defaultEnvironment: settingsProject.defaultEnvironment === profile.id ? nextID : settingsProject.defaultEnvironment }); selectedEnvironmentId = nextID; }
  function updateProfileCommand(profileID: string, componentId: string, command: string) { const profile = selectedProfile(profileID); if (profile) updateProfile({ commands: { ...profileCommands(profile), [componentId]: command } }, profileID); }
  function requestDeleteEnvironment() { const profile = selectedProfile(); if (profile && (settingsProject?.environments?.length ?? 0) > 1) environmentDeleteCandidate = profile; }
  function deleteEnvironment() { const profile = environmentDeleteCandidate; if (!profile || !settingsProject) return; updateProject({ environments: settingsProject.environments!.filter((item) => item.id !== profile.id), defaultEnvironment: settingsProject.defaultEnvironment === profile.id ? settingsProject.environments!.find((item) => item.id !== profile.id)?.id : settingsProject.defaultEnvironment }); selectedEnvironmentId = settingsProject.environments!.find((item) => item.id !== profile.id)?.id ?? ''; environmentDeleteCandidate = null; }
  async function saveSettings() { if (!settingsProject) return; saving = true; issues = []; errorMessage = ''; try { const saved = await SaveProject(settingsProject); projects = projects.some((project) => project.id === saved.id) ? projects.map((project) => project.id === saved.id ? saved : project) : [...projects, saved]; selectedProjectId = saved.id; selectedComponentIds = saved.components.map((component) => component.id); releaseEnvironment = saved.defaultEnvironment ?? saved.environments?.[0]?.id ?? 'dev'; settingsProject = structuredClone(saved); settingsIsNew = false; successMessage = 'Project saved.'; } catch (error) { errorMessage = readableError(error); issues = [{ field: 'project', message: errorMessage }]; } finally { saving = false; } }
  async function confirmDeleteProject() { if (!deleteCandidate) return; try { await DeleteProject(deleteCandidate.id); projects = projects.filter((project) => project.id !== deleteCandidate!.id); selectedProjectId = projects[0]?.id ?? ''; selectedComponentIds = projects[0]?.components.map((component) => component.id) ?? []; deleteCandidate = null; view = 'release'; successMessage = 'Project deleted.'; } catch (error) { errorMessage = readableError(error); } }
  async function saveDaliSettings() { daliSaving = true; try { daliConfig = await SaveDaliConfig(daliConfig); successMessage = 'Dali settings saved.'; } catch (error) { errorMessage = readableError(error); } finally { daliSaving = false; } }
  async function browseComponentPath(index: number) { const path = await PickDirectory(settingsProject?.components[index]?.path ?? ''); if (path) updateComponent(index, { path }); }
  async function browseOutputDirectory(index: number) { const path = await PickDirectory(settingsProject?.components[index]?.outputDirectory ?? ''); if (path) updateComponent(index, { outputDirectory: path }); }
  async function browseDaliExecutable() { const path = await PickFile(daliConfig.executable); if (path) daliConfig = { ...daliConfig, executable: path }; }
  async function openReleaseFolder(path?: string) { if (!path) return; try { await OpenReleaseFolder(path); } catch (error) { errorMessage = readableError(error); } }
  function rerun(run: RunSummary) { selectedProjectId = run.projectId; selectedComponentIds = [...run.componentIds]; releaseEnvironment = run.environment ?? ''; packageVersion = run.version ?? '1.0.0'; packageTemplate = run.filenameTemplate ?? ''; namingNames = { ...(run.approvedPackageNames ?? {}) }; operation = operationFromSummary(run.operation); view = 'release'; step = 1; resetRunState(); }
  function operationFromSummary(value: string): Operation { return value === 'build' ? 'build' : value === 'package' ? 'package' : value === 'transfer' ? 'transfer' : value === 'build-package-send' ? 'release-transfer' : 'release'; }
  function operationLabel(value: Operation) { return { build: 'Build Only', release: 'Build & Package', package: 'Package Existing Build', transfer: 'Send Packages', 'release-transfer': 'Build, Package & Send' }[value]; }
  function legacyEnvironments(project: Project | null): EnvironmentProfile[] { const ids = new Set(['dev', 'staging', 'prod']); (project?.components ?? []).forEach((component) => Object.keys(component.buildCommands ?? {}).forEach((id) => ids.add(id))); return [...ids].map((id) => ({ id, name: id === 'dev' ? 'Development' : id === 'staging' ? 'Staging' : id === 'prod' ? 'Production' : id, commands: {} })); }
  function defaultEnvironments(): EnvironmentProfile[] { return [{ id: 'dev', name: 'Development', commands: {} }, { id: 'staging', name: 'Staging', commands: {} }, { id: 'prod', name: 'Production', commands: {} }]; }
  function emptyComponent(): Component { newComponentSequence += 1; return { id: `component-${newComponentSequence}`, name: '', path: '', buildCommand: 'npm run build', buildCommands: {}, outputDirectory: 'build', package: { enabled: true, filename: '{project}-{component}-v{version}-{date}.zip' } }; }
  function uniqueEnvironmentId(items: EnvironmentProfile[]) { let id = 'qa'; let index = 2; while (items.some((item) => item.id === id)) id = `env-${index++}`; return id; }
  function statusLabel(status: string) { return status.charAt(0).toUpperCase() + status.slice(1); }
  function statusIcon(status: string) { return { ready: 'o', building: '~', packaging: '~', sending: '~', success: 'OK', completed: 'OK', failed: 'x', skipped: '-', cancelled: '!' }[status] ?? 'o'; }
  function inputValue(event: Event) { return (event.currentTarget as HTMLInputElement).value; }
  function checkedValue(event: Event) { return (event.currentTarget as HTMLInputElement).checked; }
  function selectValue(event: Event) { return (event.currentTarget as HTMLSelectElement).value; }
  function readableError(error: unknown) { return error instanceof Error ? error.message : String(error); }
  function scheduleNotificationDismissal() { if (notificationTimer) clearTimeout(notificationTimer); notificationTimer = setTimeout(() => { errorMessage = ''; successMessage = ''; notificationTimer = null; }, 3000); }
</script>

<svelte:head><title>Release Launcher</title></svelte:head>
<div class="app-shell">
  <aside class="sidebar"><div class="sidebar-brand"><img src={logo} alt="" /><div><strong>Release Launcher</strong><small>Developer workspace</small></div></div><nav aria-label="Primary navigation"><button class:active={view === 'release'} on:click={() => (view = 'release')}><span>R</span>Release</button><button class:active={view === 'projects'} on:click={() => (view = 'projects')}><span>P</span>Projects</button><button class:active={view === 'activity'} on:click={() => { view = 'activity'; void loadActivity(); }}><span>A</span>Activity</button><button class:active={view === 'settings'} on:click={() => (view = 'settings')}><span>S</span>Settings</button></nav><div class="sidebar-footer"><span class="online-dot"></span>Local workspace</div></aside>
  <div class="workspace"><header class="topbar"><div><p class="breadcrumb">{view === 'release' ? 'Release' : view === 'projects' ? 'Projects' : view === 'activity' ? 'Activity' : 'Settings'}</p><h1>{view === 'release' ? 'Prepare a release' : view === 'projects' ? 'Project configuration' : view === 'activity' ? 'Recent activity' : 'Application settings'}</h1></div><div class="context-bar"><span><small>Project</small>{selectedProject?.name ?? 'No project'}</span><span><small>Environment</small>{(activeEnvironment?.name ?? releaseEnvironment) || 'Not selected'}</span><span class:busy={operationActive} class="status-pill">{operationActive ? 'In progress' : 'Ready'}</span></div></header>
    {#if errorMessage}<div class="alert error" role="alert">{errorMessage}<button class="alert-close" on:click={() => (errorMessage = '')}>x</button></div>{/if}{#if successMessage}<div class="alert success" role="status">{successMessage}</div>{/if}
    {#if loading}<main class="card loading">Loading workspace</main>
    {:else if view === 'release'}<main class="release-page"><div class="stepper" aria-label="Release steps"><div class:current={step === 1} class:done={step > 1}><b>1</b><span>Configure</span></div><i></i><div class:current={step === 2} class:done={step > 2}><b>2</b><span>Review</span></div><i></i><div class:current={step === 3}><b>3</b><span>Run</span></div></div>
      {#if step === 1}<section class="card page-card"><div class="section-heading"><div><p class="eyebrow">Step 1 of 3</p><h2>Configure the release</h2><p>Choose what to release, where it should build, and how it should be packaged.</p></div></div><div class="config-grid"><label class="field"><span>Project</span><select value={selectedProjectId} on:change={(event) => selectProject(selectValue(event))}><option value="">Select a project</option>{#each projects as project}<option value={project.id}>{project.name}</option>{/each}</select></label><label class="field"><span>Environment profile</span><select value={releaseEnvironment} on:change={(event) => selectEnvironment(selectValue(event))}>{#each environments as environment}<option value={environment.id}>{environment.name}</option>{/each}</select></label><label class="field"><span>Release version</span><input value={packageVersion} on:input={(event) => (packageVersion = inputValue(event))} placeholder="1.0.0" /></label></div><div class="operation-picker"><div><h3>Operation</h3><p>Build &amp; Package is the recommended release path.</p></div><select value={operation} on:change={(event) => setOperation(event)}><option value="release">Build &amp; Package  Recommended</option><option value="build">Build Only</option><option value="package">Package Existing Build</option><option value="transfer">Send Packages</option><option value="release-transfer">Build, Package &amp; Send</option></select></div>
        {#if selectedProject}<section class="component-section"><div class="section-heading compact"><div><h3>Components</h3><p>Select the components included in this operation.</p></div><div class="inline-actions"><label class="compact-search"><span class="sr-only">Filter components</span><input value={componentFilter} on:input={(event) => (componentFilter = inputValue(event))} placeholder="Filter" /></label><button class="text-button" on:click={selectAllComponents}>Select all</button><button class="text-button" on:click={selectNoComponents}>None</button></div></div><div class="component-table"><div class="component-table-head"><span>Include</span><span>Component</span><span>Status</span><span>Packaging</span></div>{#each selectedProject.components.filter((component) => component.name.toLowerCase().includes(componentFilter.toLowerCase())) as component}<label class="component-table-row"><input type="checkbox" checked={selectedComponentIds.includes(component.id)} on:change={() => toggleComponent(component)} /><strong>{component.name}</strong><span class="muted">Ready</span><span class:enabled={component.package.enabled} class="tag">{component.package.enabled ? 'Enabled' : 'Disabled'}</span></label>{:else}<div class="empty-state">No components configured. Add one under Projects.</div>{/each}</div></section>{:else}<div class="empty-state">Create a project under Projects to begin a release.</div>{/if}<details class="advanced"><summary>Advanced package naming</summary><div class="advanced-content"><label class="field"><span>Filename template</span><input value={packageTemplate} on:input={(event) => (packageTemplate = inputValue(event))} placeholder="Use component templates" /><small>Tokens: {`{project}`} {`{component}`} {`{version}`} {`{date}`} {`{time}`} {`{datetime}`}</small></label></div></details><div class="sticky-actions"><button class="primary-button" disabled={!selectedProject || selectedComponentIds.length === 0 || operationStarting} on:click={continueToReview}>{operationStarting ? 'Preparing' : 'Continue to Review'}</button></div></section>
      {:else if step === 2}<section class="card page-card"><div class="section-heading"><div><p class="eyebrow">Step 2 of 3</p><h2>Review before running</h2><p>Confirm the resolved inputs. The operation will not start until you approve this plan.</p></div><span class="operation-badge">{operationLabel(operation)}</span></div><div class="review-summary"><div><small>Project</small><strong>{selectedProject?.name}</strong></div><div><small>Environment</small><strong>{activeEnvironment?.name ?? releaseEnvironment}</strong></div><div><small>Version</small><strong>{packageVersion}</strong></div><div><small>Components</small><strong>{selectedComponentIds.length} selected</strong></div></div>{#if buildReview}<div class="compact-confirm"><span class="confirm-icon">OK</span><div><h3>Build confirmation</h3><p>Build {selectedComponentIds.length} component(s) using the {activeEnvironment?.name ?? releaseEnvironment} profile. Build output will be validated before the run completes.</p></div></div>{:else if namingPlan}<div class="review-list"><div class="review-list-head"><span>Component</span><span>Approved filename</span><span>Release path</span></div>{#each namingPlan.components.filter((item) => item.selected && item.enabled) as item}<div class="review-list-row"><strong>{item.componentName}</strong><label><span class="sr-only">Filename for {item.componentName}</span><input value={namingNames[item.componentId] ?? ''} on:input={(event) => void editPackageName(item.componentId, inputValue(event))} /></label><div><code>{namingPlan.releaseDirectory}\{namingNames[item.componentId] ?? item.resolvedFilename}</code>{#if item.existing}<span class="warning-text">Existing file conflict</span>{:else}<span class="success-text">Available</span>{/if}</div></div>{/each}</div>{#if namingPlan.hasConflicts}<label class="overwrite-choice"><input type="checkbox" checked={overwrite} on:change={(event) => (overwrite = checkedValue(event))} /><span>Allow replacement of existing files after this review</span></label>{/if}{/if}{#if namingError}<div class="validation-box">{namingError}</div>{/if}<div class="sticky-actions"><button class="secondary-button" on:click={cancelFlow}> Back to Configure</button><button class="primary-button" disabled={operationStarting || (!buildReview && !namingPlan)} on:click={() => void confirmReview()}>Confirm and Run</button></div></section>
      {:else}<section class="card page-card run-page"><div class="section-heading"><div><p class="eyebrow">Step 3 of 3  {operationLabel(operation)}</p><h2>{currentRun ? currentRun.projectName : 'Starting run'}</h2><p>{currentRun?.environment ?? releaseEnvironment}  Version {currentRun && 'version' in currentRun ? currentRun.version : packageVersion}</p></div><span class:success={currentRun?.status === 'completed'} class:error={currentRun?.status === 'failed' || currentRun?.status === 'cancelled'} class="status-pill">{operationStarting ? 'Starting' : statusLabel(currentRun?.status ?? 'running')}</span></div>{#if releaseRun}<div class="progress-list">{#each releaseRun.components as item}<div class="progress-row"><div><strong>{item.componentName}</strong><small>Build: {item.buildMessage}  Package: {item.packageMessage}  Send: {item.transferMessage}</small></div><span class="stage-tags"><em class={`status-${item.buildStatus}`}>{statusIcon(item.buildStatus)} Build</em><em class={`status-${item.packageStatus}`}>{statusIcon(item.packageStatus)} Package</em><em class={`status-${item.transferStatus}`}>{statusIcon(item.transferStatus)} Send</em></span></div>{/each}</div>{:else if buildRun}<div class="progress-list">{#each buildRun.components as item}<div class="progress-row"><div><strong>{item.componentName}</strong><small>{item.message}</small></div><span class={`run-state status-${item.status}`}>{statusIcon(item.status)} {statusLabel(item.status)}</span></div>{/each}</div>{:else if packageRun}<div class="progress-list">{#each packageRun.components as item}<div class="progress-row"><div><strong>{item.componentName}</strong><small>{item.message}</small></div><span class={`run-state status-${item.status}`}>{statusIcon(item.status)} {statusLabel(item.status)}</span></div>{/each}</div>{:else if transferRun}<div class="progress-list">{#each transferRun.components as item}<div class="progress-row"><div><strong>{item.componentName}</strong><small>{item.message}</small></div><span class={`run-state status-${item.status}`}>{statusIcon(item.status)} {statusLabel(item.status)}</span></div>{/each}</div>{/if}{#if buildOutput.length}<details class="console-details"><summary>Live console output ({buildOutput.length} lines)</summary><div class="console" aria-live="polite">{#each buildOutput as line}<div class:stderr={line.stream === 'stderr'}><b>[{line.componentName}]</b> {line.text}</div>{/each}</div></details>{/if}{#if currentRun?.status === 'running' || operationStarting}<div class="run-actions"><button class="danger-button" on:click={() => void cancelOperation()}>Cancel run</button></div>{:else if currentRun}<div class="completion-actions"><button class="secondary-button" on:click={() => rerun({ runId: currentRun.id, projectId: currentRun.projectId, projectName: currentRun.projectName, environment: currentRun.environment, operation, version: 'version' in currentRun ? currentRun.version : packageVersion, componentIds: selectedComponentIds, startTime: currentRun.startTime, status: currentRun.status })}>Rerun with review</button><button class="primary-button" on:click={() => { step = 1; resetRunState(); }}>Start new release</button></div>{/if}</section>{/if}</main>
    {:else if view === 'activity'}<main class="card page-card activity-page"><div class="section-heading"><div><p class="eyebrow">Run history</p><h2>Recent activity</h2><p>Review outcomes and load an approved configuration into a new release.</p></div><button class="secondary-button" on:click={() => void loadActivity()}>Refresh</button></div><div class="filters"><select value={activityProject} on:change={(event) => (activityProject = selectValue(event))}><option value="">All projects</option>{#each projects as project}<option value={project.id}>{project.name}</option>{/each}</select><select value={activityStatus} on:change={(event) => (activityStatus = selectValue(event))}><option value="all">All statuses</option><option value="completed">Completed</option><option value="failed">Failed</option><option value="cancelled">Cancelled</option></select><select value={activityEnvironment} on:change={(event) => (activityEnvironment = selectValue(event))}><option value="all">All environments</option>{#each [...new Set(activity.map((run) => run.environment).filter(Boolean))] as environment}<option value={environment}>{environment}</option>{/each}</select></div><div class="activity-list">{#each filteredActivity as run}<article class="activity-row"><div class={`activity-icon ${run.status}`}>{statusIcon(run.status)}</div><div class="activity-main"><div><strong>{run.projectName}</strong><span class="tag">{run.environment || 'legacy'}  {operationFromSummary(run.operation) === 'release' ? 'Build & Package' : run.operation}</span></div><small>{run.version ? `v${run.version}  ` : ''}{run.componentIds.length} component(s)  {new Date(run.startTime).toLocaleString()}</small>{#if run.errorSummary}<p class="warning-text">{run.errorSummary}</p>{/if}</div>{#if run.releaseDirectory}<button class="ghost-button" on:click={() => void openReleaseFolder(run.releaseDirectory)}>Open folder</button>{/if}<button class="secondary-button" on:click={() => rerun(run)}>Load for review</button></article>{:else}<div class="empty-state large">No runs match these filters.</div>{/each}</div></main>
    {:else if view === 'projects'}<main class="settings-layout"><aside class="card project-list"><div class="section-heading compact"><h2>Projects</h2><button class="icon-button" title="Add project" on:click={openNewProject}>+</button></div>{#each projects as project}<button class:active={settingsProject?.id === project.id} class="project-list-item" on:click={() => openProjectSettings(project)}><strong>{project.name}</strong><small>{project.components.length} components  {project.environments?.length ?? 0} environments</small></button>{:else}<p class="muted">No projects yet.</p>{/each}</aside><section class="card settings-editor">{#if settingsProject}<div class="section-heading"><div><p class="eyebrow">Project configuration</p><h2>{settingsIsNew ? 'New project' : settingsProject.name}</h2></div>{#if !settingsIsNew}<button class="danger-button" on:click={() => (deleteCandidate = settingsProject)}>Delete project</button>{/if}</div><div class="subnav"><button class:active={settingsTab === 'general'} on:click={() => (settingsTab = 'general')}>General</button><button class:active={settingsTab === 'components'} on:click={() => (settingsTab = 'components')}>Components</button><button class:active={settingsTab === 'environments'} on:click={openEnvironmentProfiles}>Environment Profiles</button></div>{#if issues.length}<div class="validation-box">{#each issues as issue}<div>{issue.field}: {issue.message}</div>{/each}</div>{/if}{#if settingsTab === 'general'}<label class="field"><span>Project name</span><input value={settingsProject.name} on:input={(event) => updateProject({ name: inputValue(event) })} placeholder="LokalStore" /></label><div class="settings-note"><strong>Project profile</strong><p>Components and environment profiles stay together so a release always makes its target explicit.</p></div>{:else if settingsTab === 'components'}<div class="section-heading compact"><div><h3>Components</h3><p>Paths, build fallback commands, and package behavior.</p></div><button class="text-button" on:click={addComponent}>+ Add component</button></div>{#each settingsProject.components as component, index}<article class="component-editor"><div class="component-editor-title"><h3>{component.name || 'New component'}</h3><button class="remove-button" on:click={() => removeComponent(index)}>Remove</button></div><div class="form-grid"><label class="field"><span>Name</span><input value={component.name} on:input={(event) => updateComponent(index, { name: inputValue(event) })} /></label><div class="field"><span>Project path</span><div class="input-action"><input value={component.path} on:input={(event) => updateComponent(index, { path: inputValue(event) })} /><button class="secondary-button" on:click={() => void browseComponentPath(index)}>Browse</button></div></div><label class="field"><span>Legacy default build command</span><input value={component.buildCommand} on:input={(event) => updateComponent(index, { buildCommand: inputValue(event) })} /><small>Used when the selected profile has no component command.</small></label><div class="field"><span>Output directory</span><div class="input-action"><input value={component.outputDirectory} on:input={(event) => updateComponent(index, { outputDirectory: inputValue(event) })} /><button class="secondary-button" on:click={() => void browseOutputDirectory(index)}>Browse</button></div></div><label class="field checkbox-field"><input type="checkbox" checked={component.package.enabled} on:change={(event) => updateComponent(index, { package: { ...component.package, enabled: checkedValue(event) } })} /><span>Packaging enabled</span></label><label class="field"><span>Package filename template</span><input value={component.package.filename} on:input={(event) => updateComponent(index, { package: { ...component.package, filename: inputValue(event) } })} /></label></div></article>{:else}<div class="empty-state">Add a component above.</div>{/each}{:else}<div class="environment-editor"><div class="environment-list"><div class="section-heading compact"><h3>Profiles</h3><button class="text-button" on:click={addEnvironment}>+ Add</button></div>{#each settingsProject.environments ?? [] as environment}<button class:active={selectedEnvironmentId === environment.id} class="environment-item" on:click={() => (selectedEnvironmentId = environment.id)}><strong>{environment.name}</strong><small>{environment.id}{settingsProject.defaultEnvironment === environment.id ? '  Default' : ''}</small></button>{/each}</div><div class="environment-detail">{#if selectedEnvironmentProfile}<div class="section-heading compact"><div><h3>{selectedEnvironmentProfile.name || selectedEnvironmentProfile.id}</h3><p>Commands for the selected environment profile.</p></div><div class="inline-actions"><button class="text-button" on:click={duplicateEnvironment}>Duplicate</button><button class="remove-button" on:click={requestDeleteEnvironment}>Delete</button></div></div><div class="form-grid"><label class="field"><span>Profile name</span><input value={selectedEnvironmentProfile.name} on:input={(event) => updateProfile({ name: inputValue(event) })} /></label><label class="field"><span>Identifier</span><input value={selectedEnvironmentProfile.id} on:change={(event) => updateProfile({ id: inputValue(event).trim().toLowerCase() }, selectedEnvironmentProfile.id)} /></label><label class="field"><span>Default environment</span><select value={settingsProject.defaultEnvironment} on:change={(event) => updateProject({ defaultEnvironment: selectValue(event) })}>{#each settingsProject.environments ?? [] as environment}<option value={environment.id}>{environment.name}</option>{/each}</select></label></div><div class="command-table"><div class="command-table-head"><span>Component</span><span>Profile command</span><span>Fallback</span></div>{#each settingsProject.components as component}<div class="command-table-row"><strong>{component.name}</strong><input value={profileCommands(selectedEnvironmentProfile)[component.id] ?? ''} on:input={(event) => updateProfileCommand(selectedEnvironmentProfile.id, component.id, inputValue(event))} placeholder="Uses legacy/default command" /><small>{component.buildCommands?.[selectedEnvironmentProfile.id] || component.buildCommand || 'Not configured'}</small></div>{/each}</div>{:else}<div class="empty-state">Add an environment profile to configure commands.</div>{/if}</div></div>{/if}<div class="sticky-actions"><button class="secondary-button" on:click={() => (view = 'release')}>Cancel</button><button class="primary-button" disabled={saving} on:click={() => void saveSettings()}>{saving ? 'Saving' : 'Save project'}</button></div>{:else}<div class="empty-state large">Select a project or add a new one.</div>{/if}</section></main>
    {:else}<main class="card page-card settings-page"><div class="section-heading"><div><p class="eyebrow">Global configuration</p><h2>Settings</h2><p>Dali remains application-wide; release environments belong to each project.</p></div></div><div class="settings-note"><h3>Dali transfer</h3><p>Configure the installed Dali CLI and destination behavior for Send Packages operations.</p></div><div class="form-grid"><div class="field"><span>Dali executable</span><div class="input-action"><input value={daliConfig.executable} on:input={(event) => (daliConfig = { ...daliConfig, executable: inputValue(event) })} /><button class="secondary-button" on:click={() => void browseDaliExecutable()}>Browse</button></div></div><label class="field"><span>Peer name</span><input value={daliConfig.peerName} on:input={(event) => (daliConfig = { ...daliConfig, peerName: inputValue(event), peerAddress: '' })} /></label><label class="field"><span>Peer address</span><input value={daliConfig.peerAddress} on:input={(event) => (daliConfig = { ...daliConfig, peerAddress: inputValue(event), peerName: '' })} /></label><label class="field checkbox-field"><input type="checkbox" checked={daliConfig.auto} on:change={(event) => (daliConfig = { ...daliConfig, auto: checkedValue(event) })} /><span>Auto-select a single peer</span></label><label class="field checkbox-field"><input type="checkbox" checked={daliConfig.wait} on:change={(event) => (daliConfig = { ...daliConfig, wait: checkedValue(event) })} /><span>Wait for discovery timeout</span></label></div><div class="sticky-actions"><button class="primary-button" disabled={daliSaving} on:click={() => void saveDaliSettings()}>{daliSaving ? 'Saving' : 'Save settings'}</button></div></main>{/if}
  </div>
  {#if deleteCandidate}<div class="dialog-backdrop"><div class="dialog" role="dialog" aria-modal="true"><p class="eyebrow">Delete project</p><h2>Delete {deleteCandidate.name}?</h2><p>This removes the project and its component configuration. The action cannot be undone from the workspace.</p><div class="dialog-actions"><button class="secondary-button" on:click={() => (deleteCandidate = null)}>Cancel</button><button class="danger-button" on:click={() => void confirmDeleteProject()}>Delete project</button></div></div></div>{/if}{#if environmentDeleteCandidate}<div class="dialog-backdrop"><div class="dialog" role="dialog" aria-modal="true"><p class="eyebrow">Delete environment profile</p><h2>Delete {environmentDeleteCandidate.name}?</h2><p>{settingsProject?.defaultEnvironment === environmentDeleteCandidate.id ? "This is the project default. Deleting it will switch the default to another profile." : "This removes the profile from this project."}</p><div class="dialog-actions"><button class="secondary-button" on:click={() => (environmentDeleteCandidate = null)}>Cancel</button><button class="danger-button" on:click={deleteEnvironment}>Delete profile</button></div></div></div>{/if}
</div>
